typedef float vm_num_t;

class stringx;

class script_object
{
public:
  const stringx& get_name() const;
};

class vm_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_object* get_instance() const;
  vm_executable* get_executable() const;
};

class stringx
{
protected:
  char* chars;
  void* my_buf;
};

stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);
void error(const char*, ...);

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };
  protected:
    char* name;
  public:
    function(script_library_class* slc, const char* n);
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class str_list
{
  stringx* start;
  stringx* finish;
  stringx* end_of_storage;
public:
  unsigned size() const { return finish - start; }
  stringx& operator[](unsigned index) { return start[index]; }
};

typedef str_list* vm_str_list_t;
typedef const stringx* vm_str_t;

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )

#define SLF_DONE \
  return true

class slf_str_list_get_index_t : public script_library_class::function
  {
  public:
    // constructor required
    slf_str_list_get_index_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
    // library function parameters
    struct parms_t
      {
      // parameters
		  vm_str_list_t me;
		  vm_num_t index;
      };
    // library function execution
    virtual bool operator()(vm_stack& stack,entry_t entry)
      {
      SLF_PARMS;
	    #ifndef BUILD_BOOTABLE
		  if((parms->index >= parms->me->size()) || (parms->index < 0))
			  error("Index out of range %d", (int)parms->index);
	    #endif
	    vm_str_t result = &(*parms->me)[(int)parms->index];
      SLF_RETURN;
      SLF_DONE;
      }
  };
